// Helper function to get publications for a research area
function getPublicationsForResearchArea(areaId) {
    const mapping = researchAreaMappings[areaId];
    if (!mapping) {
        console.warn(`Research area '${areaId}' not found in AI classifications`);
        return { publications: [], count: 0 };
    }
    
    return mapping;
}

// Helper function to get classification for a specific publication
function getPublicationClassification(pubId) {
    return aiClassifications[pubId] || null;
}

// Export for use in other scripts
if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        aiClassifications,
        researchAreaMappings,
        getPublicationsForResearchArea,
        getPublicationClassification
    };
}
